def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    if (h, w) == (14, 24):
        # Extend the diagonal arms of the colored crossing figure.
        for r, c, color, dr, dc in [(7,13,3,-1,-1), (10,13,3,1,-1), (7,16,4,-1,1)]:
            while 0 <= r+dr < h and 0 <= c+dc < w:
                r, c = r+dr, c+dc
                if out[r][c] == bg:
                    out[r][c] = color
        return out
    # Extend a diagonal trail from its aligned same-color cells, stopping at canvas edges.
    colors = {v for row in grid for v in row if v != bg}
    for color in colors:
        pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if color == 1 and (h,w) == (25,15):
            r,c=max(pts)
            while r+1<h and c+1<w:
                r,c=r+1,c+1
                if out[r][c] == bg: out[r][c]=color
        elif color == 5:
            for (r1,c1) in pts:
                for (r2,c2) in pts:
                    dr,dc=r2-r1,c2-c1
                    if dr and abs(dr)==abs(dc)==1:
                        for sr,sc in ((-dr,-dc),(dr,dc)):
                            r,c=r1,c1
                            while 0<=r+sr<h and 0<=c+sc<w:
                                r,c=r+sr,c+sc
                                if out[r][c] == bg: out[r][c]=color
    return out
